.character-page { min-height: 100%; padding: 16px; color: #f7f7fb; background: #242438; }
.character-toolbar { display: grid; grid-template-columns: auto auto minmax(0, 1fr) auto auto; gap: 8px; align-items: center; }
.character-toolbar h2 { margin: 0; text-align: center; }
.character-toolbar button { padding: 8px 12px; color: inherit; background: #3a3a56; border: 1px solid #66668c; border-radius: 8px; }
.character-toolbar button:disabled { opacity: 0.45; }
.character-status { min-height: 1.5em; color: #c8c8e8; }
.character-rows { margin: 0; padding: 12px; overflow: auto; white-space: pre-wrap; background: #1b1b2b; border-radius: 10px; }

page.js.content:
// page.js
var ACTION_LABELS = Object.freeze({
  back: "返回",
  previousTable: "上一张",
  nextTable: "下一张",
  editCurrentTable: "编辑"
});
function actionMessage(action, result) {
  if (result?.ok) return `${ACTION_LABELS[action]}请求已提交`;
  if (result?.status === "unavailable") return `${ACTION_LABELS[action]}不可用`;
  if (result?.status === "stale") return "页面已失效";
  return result?.message || `${ACTION_LABELS[action]}失败`;
}
export function mount(context) {
  const root = context.root;
  const title = root.querySelector("#title");
  const rows = root.querySelector("#rows");
  const status = root.querySelector("#status");
  const previous = root.querySelector("#previous");
  const next = root.querySelector("#next");
  let disposed = false;
  const render = (state = context.getState()) => {
    if (disposed || !state) return;
    title.textContent = state.tableName;
    const header = state.headers.join(" / ");
    const body = state.rows.map((row) => row.map((value) => String(value ?? "")).join(" / "));
    rows.textContent = [header, ...body].filter(Boolean).join("\n");
    previous.disabled = !state.canPrevious;
    next.disabled = !state.canNext;
  };
  const handleClick = async (event) => {
    const button = event.target.closest?.("[data-action]");
    const action = button?.dataset?.action;
    if (disposed || !action || typeof context.actions[action] !== "function") return;
    button.disabled = true;
    const result = await context.actions[action]();
    if (disposed) return;
    status.textContent = actionMessage(action, result);
    render();
  };
  root.addEventListener("click", handleClick);
  const unsubscribe = context.subscribe(render);
  render();
  return () => {
    if (disposed) return;
    disposed = true;
    root.removeEventListener("click", handleClick);
    unsubscribe();
  };
}
